import csv, zipfile, collections

with zipfile.ZipFile('../inputs/gtfs/sample_city_gtfs.zip') as z:
    trips = {r['trip_id']: r['route_id'] for r in csv.DictReader(z.open('trips.txt'))}

stops = {}
with open('t05_clean_stops.csv', newline='') as f:
    for r in csv.DictReader(f):
        stops[r['stop_id']] = (r['stop_name'], r['stop_lat'], r['stop_lon'])

dep = collections.Counter()
routes = collections.defaultdict(set)
first = {}
last = {}
with open('t05_clean_stop_times.csv', newline='') as f:
    for r in csv.DictReader(f):
        sid = r['stop_id']
        t = r['departure_time']
        dep[sid] += 1
        rid = trips.get(r['trip_id'])
        if rid is not None:
            routes[sid].add(rid)
        if sid not in first or t < first[sid]:
            first[sid] = t
        if sid not in last or t > last[sid]:
            last[sid] = t

with open('t06_stop_service_intensity.csv', 'w', newline='') as f:
    w = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
    w.writerow(['stop_id','stop_name','stop_lat','stop_lon','n_departures','n_routes','first_departure','last_departure'])
    for sid, (name, lat, lon) in stops.items():
        w.writerow([sid, name, lat, lon, dep.get(sid, 0), len(routes.get(sid, ())), first.get(sid, ''), last.get(sid, '')])
print("done")
